-- Catálogo inicial de Ferretería Los Maestros (base dblosmaestros).
-- Misma estructura y datos que la base original: la categoría se guarda como texto.

CREATE TABLE IF NOT EXISTS public.catalogo_prod (
    id_codigo       character varying(255) NOT NULL PRIMARY KEY,
    categoria       character varying(255),
    subcategoria    character varying(255),
    nombre_producto character varying(255),
    marca           character varying(255),
    unidad          character varying(255),
    p_compra_clp    integer,
    p_venta_clp     integer,
    stock           integer,
    stock_minimo    integer,
    imagen_url      character varying(255)
);

ON CONFLICT (id_codigo) DO NOTHING;
